package client

import "slices"

type PatchFile struct {
	Path   string
	SHA256 string
}

func (p BuildProfile) Modules() []PatchFile {
	files := []PatchFile{
		{Path: "scripts/Battle.luac", SHA256: p.BattleSHA256},
		{Path: "scripts/PanelLogin.luac", SHA256: p.LoginSHA256},
		{Path: "scripts/ServerClient.luac", SHA256: p.ServerClientSHA256},
		{Path: "scripts/PanelFriendTip.luac", SHA256: p.FriendTipSHA256},
		{Path: "scripts/FriendInfo.luac", SHA256: p.FriendInfoSHA256},
		{Path: "scripts/FriendComp.luac", SHA256: p.FriendCompSHA256},
		{Path: "scripts/BattleComp.luac", SHA256: p.BattleCompSHA256},
		{Path: "scripts/BattleNewStage.luac", SHA256: p.BattleStageSHA256},
		{Path: "scripts/SceneTimeControlComp.luac", SHA256: p.SceneTimeSHA256},
		{Path: "scripts/UniSDKHandler.luac", SHA256: p.PaymentSHA256},
		{Path: "scripts/PatchUtils.luac", SHA256: p.PatchUtilsSHA256},
		{Path: "scripts/Status.luac", SHA256: p.PatchStatusSHA256},
		{Path: "scripts/LogicInterface.luac", SHA256: p.LogicSHA256},
		{Path: "scripts/AIEngine.luac", SHA256: p.AIEngineSHA256},
		{Path: "scripts/PanelBattleNew.luac", SHA256: p.BattlePanelSHA256},
		{Path: "scripts/ResolutionTool.luac", SHA256: p.WindowSHA256},
	}
	return append(files, retailLocalizationModules[:]...)
}

func (p BuildProfile) Resources() []PatchFile {
	return slices.Clone(retailLocalizationResources[:])
}

